// One place that reads the Twilio body. Everything downstream works on this flat
// item, so no later HTTP node can shadow the call facts.
const b = $json.body || {};
return [{ json: {
  callSid: b.CallSid || 'unknown',
  from: b.From || 'unknown caller',
  fromName: b.FromName || '',
  to: b.To || '',
  callStatus: b.CallStatus || '',
  speech: (b.SpeechResult || '').trim(),
  recordingUrl: b.RecordingUrl || '',
  dialStatus: b.DialCallStatus || '',
  transcription: (b.TranscriptionText || '').trim(),
  transcriptionStatus: b.TranscriptionStatus || ''
} }];

