// The greeting comes from the business profile the customer filled in.
const profile = ($('Load Profile (greeting)').first().json.profile) || {};
const tz = $env.FRONTLINE_TZ || 'America/Los_Angeles';
const voice = $env.FRONTLINE_VOICE || 'Polly.Joanna-Neural';
const base = ($env.FRONTLINE_PUBLIC_URL || '').replace(/\/+$/, '');
const action = base ? base + '/webhook/frontline-voice-2p' : '';

function parseHours(spec, defStart, defEnd) {
  const found = String(spec || '').toLowerCase().match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)/g);
  if (!found || found.length < 2) return [defStart, defEnd];
  const to24 = (t) => {
    const m = t.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)/);
    let h = parseInt(m[1], 10) % 12;
    if (m[3] === 'pm') h += 12;
    return h + (m[2] ? parseInt(m[2], 10) / 60 : 0);
  };
  return [to24(found[0]), to24(found[found.length - 1])];
}
function dayOpen(spec, dayIdx) {
  const s = String(spec || '').toLowerCase();
  if (!s.trim()) return true;
  const short = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  const idx = (w) => short.indexOf(String(w).slice(0, 3));
  const range = s.match(/([a-z]+)\s*(?:-|to)\s*([a-z]+)/);
  if (range) {
    const a = idx(range[1]), b = idx(range[2]);
    if (a >= 0 && b >= 0) return a <= b ? (dayIdx >= a && dayIdx <= b) : (dayIdx >= a || dayIdx <= b);
  }
  const names = s.match(/(sun|mon|tue|wed|thu|fri|sat)[a-z]*/g) || [];
  return names.length ? names.some(n => idx(n) === dayIdx) : true;
}

const local = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const hour = local.getHours() + local.getMinutes() / 60;
const [openAt, closeAt] = parseHours(profile.hours, 8, 18);
const inHours = dayOpen(profile.days_open, local.getDay()) && hour >= openAt && hour < closeAt;

const say = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const biz = profile.business_name || 'our office';
const hoursText = profile.hours || '8am to 6pm';
const daysText = profile.days_open || 'Monday to Friday';

const spoken = inHours
  ? `Thanks for calling ${biz}. Are you calling about service, a purchase, or would you like to leave a message?`
  : `Thanks for calling ${biz}. Our office is closed right now. Our hours are ${hoursText}, ${daysText}. Please say what you need and we will follow up, or leave a message after the tone.`;

const twiml = inHours
  ? `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">${say(spoken)}</Say><Gather input="speech" action="${action}" speechTimeout="auto" timeout="6" language="en-US" /></Response>`
  : `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">${say(spoken)}</Say><Record action="${action}" transcribe="true" transcribeCallback="${action}" maxLength="90" playBeep="true" /></Response>`;

return [{ json: { twiml, afterHours: !inHours, openAt, closeAt, tz, business: biz } }];

// Routing across the Frontline agent suite, sticky per call.
const call = $('Read Call').first().json || {};
const sess = $json.session || {};
const text = (call.speech || '').toLowerCase();
const rules = [
  { agent: 'concierge', why: 'appointment/booking language',
    re: /\b(book|booking|appointment|schedule|reschedule|reserve|reservation|availability)\b/ },
  { agent: 'closeter',  why: 'price/sale/service language',
    re: /\b(price|pricing|cost|quote|how much|buy|purchase|order|install|installation|repair|service call|emergency)\b/ },
  { agent: 'clerk',     why: 'paperwork/billing language',
    re: /\b(invoice|receipt|records|document|paperwork|billing|account|statement|tax)\b/ },
];
let agent = sess.agent || 'greet';
let route = agent === 'greet' ? 'default reception' : 'continuing with ' + agent;
for (const r of rules) {
  if (r.re.test(text)) { agent = r.agent; route = r.why; break; }
}
return [{ json: {
  ...call,
  utterance: call.speech,
  agent,
  route_reason: route,
  history: (sess.history || []).slice(-8),
  turn: (sess.history || []).length + 1
} }];

