// Runs in the background after Twilio already has its hold audio.
const asked = $json || {};
const ctx = $('Pick Agent').first().json || {};
let reply = (asked.reply || '').trim();
if (!reply) reply = "I'm sorry, I did not catch that. Could you say it again?";

const history = (ctx.history || []).slice();
if (ctx.utterance) history.push({ role: 'caller', content: ctx.utterance });
history.push({ role: 'assistant', content: reply });

const wantsHuman = /\b(human|person|manager|owner|technician|tech|representative|someone|transfer|speak to|real person)\b/i.test(ctx.utterance || '');
const forwardTo = ($env.FRONTLINE_FORWARD_TO || '').trim();

return [{ json: {
  sessionId: ctx.callSid,
  patch: {
    reply,
    history: history.slice(-10),
    agent: ctx.agent,
    from: ctx.from,
    forward: wantsHuman && !!forwardTo,
    forward_to: forwardTo,
    gateway_ok: asked.ok !== false,
    gateway_mode: asked.mode || '',
    gateway_error: asked.error || '',
    answered_at: new Date().toISOString()
  }
} }];

// Twilio Redirect reposts the call params and keeps our ?n= in the query string.
const b = $json.body || {};
const q = $json.query || {};
const n = parseInt(q.n || '0', 10) || 0;
return [{ json: {
  callSid: b.CallSid || q.sid || '',
  from: b.From || '',
  n,
  keep_polling: n < 20 ? 'yes' : 'no'     // decided here, not in an IF comparison
} }];

const say = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
// Phase two: the answer is in the session store, hand it to Twilio.
const sess = $json.session || {};
const poll = $('Read Poll').first().json || {};
const reply = (sess.reply || '').trim() || "I'm sorry, I didn't catch that. Could you say it again?";
const voice = $env.FRONTLINE_VOICE || 'Polly.Joanna-Neural';
const base = ($env.FRONTLINE_PUBLIC_URL || '').replace(/\/+$/, '');
const action = base ? base + '/webhook/frontline-voice-2p' : '';
const forwardTo = ($env.FRONTLINE_FORWARD_TO || '').trim();

if (sess.forward && forwardTo) {
  return [{ json: { forward: true, twiml:
    `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">One moment, connecting you now.</Say><Dial timeout="20" action="${action}">${forwardTo}</Dial></Response>` } }];
}

const gather = action
  ? `<Gather input="speech" action="${action}" speechTimeout="auto" timeout="6" language="en-US" />`
  : '<Hangup/>';
return [{ json: { forward: false, twiml:
  `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">${say(reply)}</Say>${gather}</Response>` } }];

const say = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
// Out of polling budget: stop the loop, take a message, leave a callback task.
const poll = $('Read Poll').first().json || {};
const voice = $env.FRONTLINE_VOICE || 'Polly.Joanna-Neural';
const base = ($env.FRONTLINE_PUBLIC_URL || '').replace(/\/+$/, '');
const action = base ? base + '/webhook/frontline-voice-2p' : '';
const spoken = "Sorry, this is taking longer than expected. Please leave your name, your business, and a number after the tone, and we will call you back.";
return [{ json: {
  from: poll.from || 'unknown caller',
  twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">${say(spoken)}</Say><Record action="${action}" transcribe="true" transcribeCallback="${action}" maxLength="90" playBeep="true" /></Response>`
} }];

